<script setup>
import {computed} from 'vue';
const props=defineProps({job:Object,analytical:Boolean});
const emit=defineEmits(['section','document','finding']);
const stats=computed(()=>props.job.analytics||{}),overview=computed(()=>stats.value.overview||{});
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const labels={critical:'Crítica',high:'Alta',medium:'Média',low:'Baixa',info:'Informativa',arithmetic:'Aritmética',classification:'Classificação fiscal',duplicate:'Duplicidades',economic:'Análise econômica',bookkeeping:'Escrituração',coverage:'Cobertura',structural:'Estrutura',tax:'Tributos'};
const components={vProd:'Produtos',vServ:'Serviços',vFrete:'Frete',vSeg:'Seguro',vOutro:'Outras despesas',vII:'II',vDesc:'Desconto',vPIS:'PIS',vCOFINS:'Cofins',vICMS:'ICMS',vICMSUFDest:'ICMS UF destino',vFCP:'FCP',vFCPUFDest:'FCP UF destino',vICMSMono:'ICMS monofásico',vISSQN:'ISSQN',vIS:'Imposto Seletivo'};
const cards=computed(()=>[['Documentos elegíveis',overview.value.documents||0,`${overview.value.items||0} itens analisados`],['Valor dos documentos',money(overview.value.total_value),'Amostra dentro do período'],['Base IBS/CBS informada',money(overview.value.ibs_cbs_base),'Valor declarado nos XMLs'],['IBS + CBS informados',money(Number(overview.value.ibs_value||0)+Number(overview.value.cbs_value||0)),'Sem presunção de crédito'],['Entradas',money(overview.value.input_value),`${overview.value.input_count||0} documentos`],['Saídas',money(overview.value.output_value),`${overview.value.output_count||0} documentos`],['Classificações conferidas',stats.value.classification_ok||0,'NCM / EX / CST / cClassTrib'],['Achados abertos',stats.value.open_findings||0,'Abertos ou em revisão']]);
const nf=ref=>props.job.result?.documents.find(d=>d.document_ref===ref)?.number||'Lote';
</script>
<template>
<div class="audit-kpis" v-if="!analytical"><article v-for="([label,value,note],n) in cards" :key="label" :class="{attention:n===7}"><span>{{label}}</span><strong>{{value}}</strong><small>{{note}}</small></article></div>
<div class="audit-two-columns"><section class="analysis-card"><h3>{{analytical?'Severidade dos achados':'Conclusão da amostra'}}</h3><template v-if="!analytical"><p>{{overview.documents||0}} documentos elegíveis; {{stats.comparable_items||0}} itens com recálculo comparável e {{stats.not_recalculated_items||0}} sem recálculo.</p><p>{{stats.excluded_documents||0}} documentos cancelados ou fora do período estão separados dos totais.</p><p>Catálogo: <strong>{{job.snapshot.catalog?.name||'Não informado'}}</strong></p><button class="text-button" @click="emit('section','analysis')">Examinar bases, diferenças e cobertura →</button></template><div v-else v-for="(count,key) in stats.severity_counts" :key="key" class="analysis-bar"><span>{{labels[key]||key}}</span><div><i :class="key" :style="{width:Math.max(3,count/Math.max(1,overview.findings)*100)+'%'}"/></div><b>{{count}}</b></div></section><section class="analysis-card"><h3>{{analytical?'Camadas de análise':'Ações prioritárias'}}</h3><template v-if="!analytical"><ol v-if="stats.priorities?.length" class="priorities"><li v-for="f in stats.priorities.slice(0,5)" :key="f.id"><button @click="emit('finding',f)"><span :class="['severity-dot',f.severity]"/><strong>{{f.title}}</strong><small>NF {{nf(f.document_ref)}} · {{f.rule_code}}</small></button><p>{{f.recommended_action||f.description}}</p></li></ol><p v-else>Nenhum achado aberto ou em revisão.</p></template><div v-else v-for="(count,key) in stats.category_counts" :key="key" class="category-row"><span>{{labels[key]||key}}</span><strong>{{count}}</strong></div></section></div>
<template v-if="analytical"><section class="analysis-card"><h3>Como a base de IBS/CBS foi formada</h3><p class="formula">vProd + vServ + vFrete + vSeg + vOutro + vII − vDesc − vPIS − vCOFINS − vICMS − vICMSUFDest − vFCP − vFCPUFDest − vICMSMono − vISSQN + vIS</p><p class="note">Fórmula recuperada UB16-10. Comparativo dos mesmos {{stats.comparable_items||0}} itens efetivamente recalculados; diferenças = XML menos recálculo. Cenários sem cobertura não são tratados como zero.</p><div class="table-scroll"><table><thead><tr><th>Tributo / base</th><th>XML original</th><th>Recálculo</th><th>Diferença</th></tr></thead><tbody><tr v-for="r in stats.tax_comparison" :key="r.label"><td>{{r.label}}</td><td>{{r.items?money(r.original):'Não comparável'}}</td><td>{{r.items?money(r.recalculated):'Não recalculado'}}</td><td :class="{difference:r.items&&Number(r.difference)!==0}">{{r.items?money(r.difference):'Não comparável'}}</td></tr></tbody></table></div><details><summary>Componentes consolidados da base</summary><div class="table-scroll"><table><thead><tr><th>Componente</th><th>Sinal</th><th>Valor</th></tr></thead><tbody><tr v-for="r in stats.components?.filter(r=>Number(r.value))" :key="r.code"><td>{{components[r.code]||r.code}} · {{r.code}}</td><td>{{r.sign}}</td><td>{{money(r.value)}}</td></tr></tbody></table></div></details></section><section class="analysis-card"><h3>Cobertura e método preservados</h3><p>{{stats.not_recalculated_items||0}} itens sem recálculo. O resultado não equivale a apuração ou validação normativa.</p><ul><li v-for="limit in job.coverage.limitations" :key="limit">{{limit}}</li></ul><p>{{job.coverage.auxiliary}}</p><dl class="method"><dt>Motor</dt><dd>{{job.snapshot.engine}}</dd><dt>Catálogo</dt><dd>{{job.snapshot.catalog?.name||'Sem catálogo'}}</dd><dt>SHA-256 do retrato</dt><dd><code>{{job.result?.snapshot_sha256}}</code></dd></dl></section></template>
<div v-else class="audit-quick-actions"><button class="button primary" @click="emit('section','documents')">Consultar documentos e itens</button><button class="button outline" @click="emit('section','findings')">Analisar achados</button><button class="button outline" @click="emit('section','reports')">Abrir relatórios</button></div>
</template>
<style scoped>
.audit-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}.audit-kpis article{padding:16px;background:#f2f6f8;border:1px solid #dce5e9;border-radius:8px;display:flex;flex-direction:column;gap:7px}.audit-kpis span{font-size:12px;color:#527084}.audit-kpis strong{font-size:22px;color:#163e52;letter-spacing:-.4px}.audit-kpis small{font-size:11px;color:#718793}.audit-kpis article.attention{background:#fff3ed;border-color:#f0d9cc}.audit-kpis .attention strong{color:#a44332}.audit-two-columns{display:grid;grid-template-columns:1fr 1.25fr;gap:16px}.analysis-card{border:1px solid #dce5e9;border-radius:8px;padding:18px;margin-bottom:16px;min-width:0}.analysis-card h3{font-size:15px;color:#183e50;margin-bottom:12px}.analysis-card p{font-size:13px;line-height:1.6;margin:8px 0}.priorities{padding-left:20px;margin:0}.priorities li{padding:6px 0 10px}.priorities button{background:none;border:0;text-align:left;cursor:pointer;color:#234759;padding:0}.priorities small{display:block;color:#68808f;font-size:11px;margin:4px 0}.priorities p{font-size:12px;color:#5f7784;margin:0}.severity-dot{width:7px;height:7px;background:#72919f;border-radius:50%;display:inline-block;margin-right:6px}.critical,.high{background:#b74f42!important}.medium{background:#c39030!important}.analysis-bar{display:flex;align-items:center;gap:10px;font-size:12px;margin:12px 0}.analysis-bar>span{width:70px}.analysis-bar>div{flex:1;height:7px;background:#eef2f4;border-radius:7px;overflow:hidden}.analysis-bar i{display:block;height:7px;background:#4e887c}.category-row{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid #edf1f4;font-size:12px}.formula{padding:12px;background:#edf4f3;border-left:3px solid #225f57;font-family:monospace}.note{color:#617b8b}.difference{color:#a34533;font-weight:700;background:#fff2e9}.method{display:grid;grid-template-columns:150px minmax(0,1fr);font-size:12px;gap:10px}.method dd{margin:0;overflow-wrap:anywhere}.audit-quick-actions{display:flex;gap:10px;flex-wrap:wrap}summary{padding:12px 0;cursor:pointer}li{line-height:1.7}td{font-variant-numeric:tabular-nums}@media(max-width:1000px){.audit-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.audit-two-columns{grid-template-columns:1fr}}@media(max-width:500px){.audit-kpis{gap:8px}.audit-kpis article{padding:12px}.audit-kpis strong{font-size:18px}.method{grid-template-columns:1fr}}
</style>
